   154→template<typename scalar_t, typename cache_t, bool is_fp8_e5m2_kv_cache>
   155→__global__ void reshape_and_cache_kernel(
   156→  const scalar_t* __restrict__ key,           // [num_tokens, num_heads, head_size]
   157→  const scalar_t* __restrict__ value,         // [num_tokens, num_heads, head_size]
   158→  cache_t* __restrict__ key_cache,            // [num_blocks, num_heads, head_size/x, block_size, x]
   159→  cache_t* __restrict__ value_cache,          // [num_blocks, num_heads, head_size, block_size]
   160→  const int64_t* __restrict__ slot_mapping,   // [num_tokens]
   161→  const int key_stride,
   162→  const int value_stride,
   163→  const int num_heads,
   164→  const int head_size,
   165→  const int block_size,
   166→  const int x) {
   167→  const int64_t token_idx = blockIdx.x;
   168→  const int64_t slot_idx = slot_mapping[token_idx];
   169→  if (slot_idx < 0) {
   170→    // Padding token that should be ignored.
   171→    return;
   172→  }
   173→
   174→  const int64_t block_idx = slot_idx / block_size;
   175→  const int64_t block_offset = slot_idx % block_size;
   176→
   177→  const int n = num_heads * head_size;
   178→  for (int i = threadIdx.x; i < n; i += blockDim.x) {
   179→    const int64_t src_key_idx = token_idx * key_stride + i;
   180→    const int64_t src_value_idx = token_idx * value_stride + i;
   181→
   182→    const int head_idx = i / head_size;
   183→    const int head_offset = i % head_size;
   184→    const int x_idx = head_offset / x;
   185→    const int x_offset = head_offset % x;
   186→
   187→    const int64_t tgt_key_idx = block_idx * num_heads * (head_size / x) * block_size * x
   188→                                + head_idx * (head_size / x) * block_size * x
   189→                                + x_idx * block_size * x
   190→                                + block_offset * x
   191→                                + x_offset;
   192→    const int64_t tgt_value_idx = block_idx * num_heads * head_size * block_size
   193→                                  + head_idx * head_size * block_size
   194→                                  + head_offset * block_size
   195→                                  + block_offset;
   196→    scalar_t tgt_key = key[src_key_idx];
   197→    scalar_t tgt_value = value[src_value_idx];
   198→    if constexpr (is_fp8_e5m2_kv_cache) {
   199→#ifdef ENABLE_FP8_E5M2
   200→      key_cache[tgt_key_idx] = fp8_e5m2_unscaled::vec_conversion<uint8_t, scalar_t>(tgt_key);
   201→      value_cache[tgt_value_idx] = fp8_e5m2_unscaled::vec_conversion<uint8_t, scalar_t>(tgt_value);
   202→#else
   203→      assert(false);
   204→#endif
   205→    } else {
   206→      key_cache[tgt_key_idx] = tgt_key;
   207→      value_cache[tgt_value_idx] = tgt_value;
   208→    }
   209→  }
   210→}
   211→
   212→} // namespace vllm
   213→
   214→#define CALL_RESHAPE_AND_CACHE(KV_T, CACHE_T, IS_FP8_E5M2_KV_CACHE)                                \
   215→  vllm::reshape_and_cache_kernel<KV_T, CACHE_T, IS_FP8_E5M2_KV_CACHE><<<grid, block, 0, stream>>>( \
   216→    reinterpret_cast<KV_T*>(key.data_ptr()),                                                       \
   217→    reinterpret_cast<KV_T*>(value.data_ptr()),                                                     \
   218→    reinterpret_cast<CACHE_T*>(key_cache.data_ptr()),                                              \
   219→    reinterpret_cast<CACHE_T*>(value_cache.data_ptr()),                                            \
   220→    slot_mapping.data_ptr<int64_t>(),                                                              \
   221→    key_stride,                                                                                    \
   222→    value_stride,                                                                                  \
   223→    num_heads,                                                                                     \
   224→    head_size,                                                                                     \
   225→    block_size,                                                                                    \
   226→    x);
   227→
   228→void reshape_and_cache(
   229→  torch::Tensor& key,           // [num_tokens, num_heads, head_size]
   230→  torch::Tensor& value,         // [num_tokens, num_heads, head_size]
   231→  torch::Tensor& key_cache,     // [num_blocks, num_heads, head_size/x, block_size, x]
   232→  torch::Tensor& value_cache,   // [num_blocks, num_heads, head_size, block_size]
   233→  torch::Tensor& slot_mapping,  // [num_tokens]
   234→  const std::string& kv_cache_dtype)
   235→{
   236→  int num_tokens = key.size(0);
   237→  int num_heads = key.size(1);
   238→  int head_size = key.size(2);
   239→  int block_size = key_cache.size(3);
   240→  int x = key_cache.size(4);
   241→
   242→  int key_stride = key.stride(0);
   243→  int value_stride = value.stride(0);
   244→
   245→  dim3 grid(num_tokens);
   246→  dim3 block(std::min(num_heads * head_size, 512));
   247→  const at::cuda::OptionalCUDAGuard device_guard(device_of(key));
   248→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   249→  if (kv_cache_dtype == "auto") {
   250→    if (key.dtype() == at::ScalarType::Float) {
   251→      CALL_RESHAPE_AND_CACHE(float, float, false);
   252→    } else if (key.dtype() == at::ScalarType::Half) {
   253→      CALL_RESHAPE_AND_CACHE(uint16_t, uint16_t, false);
   254→    } else if (key.dtype() == at::ScalarType::BFloat16) {
   255→      CALL_RESHAPE_AND_CACHE(__nv_bfloat16, __nv_bfloat16, false);
   256→    }
   257→  } else if (kv_cache_dtype == "fp8_e5m2") {
   258→    if (key.dtype() == at::ScalarType::Float) {
   259→      CALL_RESHAPE_AND_CACHE(float, uint8_t, true);
   260→    } else if (key.dtype() == at::ScalarType::Half) {
   261→      CALL_RESHAPE_AND_CACHE(uint16_t, uint8_t, true);
   262→    } else if (key.dtype() == at::ScalarType::BFloat16) {
   263→      CALL_RESHAPE_AND_CACHE(__nv_bfloat16, uint8_t, true);
   264→    }
   265→  } else {
   266→    TORCH_CHECK(false, "Unsupported data type of kv cache: ", kv_cache_dtype);
   267→  }
   268→}
