   272→template<typename Tout, typename Tin>
   273→__global__ void convert_fp8_e5m2_kernel(
   274→  const Tin* __restrict__ src_cache,
   275→  Tout* __restrict__ dst_cache,
   276→  const int64_t block_stride) {
   277→  const int64_t block_idx = blockIdx.x;
   278→  for (int i = threadIdx.x; i < block_stride; i += blockDim.x) {
   279→    int64_t idx = block_idx * block_stride + i;
   280→#ifdef ENABLE_FP8_E5M2
   281→    dst_cache[idx] = fp8_e5m2_unscaled::vec_conversion<Tout, Tin>(src_cache[idx]);
   282→#else
   283→    assert(false);
   284→#endif
   285→  }
   286→}
   287→
   288→} // namespace vllm
   289→
   290→#define CALL_CONVERT_FP8_E5M2(Tout, Tin)                                 \
   291→  vllm::convert_fp8_e5m2_kernel<Tout, Tin><<<grid, block, 0, stream>>>(  \
   292→    reinterpret_cast<Tin*>(src_cache.data_ptr()),                        \
   293→    reinterpret_cast<Tout*>(dst_cache.data_ptr()),                       \
   294→    block_stride);
   295→
   296→void convert_fp8_e5m2(
   297→  torch::Tensor& src_cache,
   298→  torch::Tensor& dst_cache)
   299→{
   300→  int64_t num_blocks = src_cache.size(0);
   301→  int64_t block_stride = src_cache.stride(0);
   302→
   303→  dim3 grid(num_blocks);
   304→  dim3 block(std::min(block_stride, int64_t(512)));
   305→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   306→
   307→  if (src_cache.dtype() == at::ScalarType::Float) {
   308→    CALL_CONVERT_FP8_E5M2(uint8_t, float);
   309→  } else if (src_cache.dtype() == at::ScalarType::Half) {
   310→    CALL_CONVERT_FP8_E5M2(uint8_t, uint16_t);
   311→  } else if (src_cache.dtype() == at::ScalarType::BFloat16) {
   312→    CALL_CONVERT_FP8_E5M2(uint8_t, __nv_bfloat16);
   313→  } else if (dst_cache.dtype() == at::ScalarType::Float) {
   314→    CALL_CONVERT_FP8_E5M2(float, uint8_t);
   315→  } else if (dst_cache.dtype() == at::ScalarType::Half) {
   316→    CALL_CONVERT_FP8_E5M2(uint16_t, uint8_t);
   317→  } else if (dst_cache.dtype() == at::ScalarType::BFloat16) {
   318→    CALL_CONVERT_FP8_E5M2(__nv_bfloat16, uint8_t);
   319→  }
   320→}
