  const std::string& kv_cache_dtype)
{
  // NOTE(woosuk): key.size(0) can be different from slot_mapping.size(0)
  // because of padding for CUDA graphs. In this case, slot_mapping.size(0)
  // represents the actual number of tokens before padding. We use
  // slot_mapping.size(0) as the number of tokens to avoid unnecessary work.
